import { css } from "./css"
import { node_append } from "./dom"
import { sym_elt_init } from "./symbols"

import type { Attrs, ElementMap, EmptyAttributes, Renderable } from "./types"

////////////////////////////////////////////////////////

css`e-obs,e-if,e-switch,e-repeat,e-repeat-scroll,e-virtual-scroll,e-repeat-item,e-repeat-separator,e-repeat-prefix,e-repeat-suffix,e-repeat-empty,e-app,e-app-view,e-lang,e-unpromise {
  display: contents
}
`

/** A RefChild given to ElementClassFn functions to insert their content */
export class RefChild extends Comment {
  private with_content: ((refchild: RefChild) => Renderable<Node>) | null = null
  private content_ref: Comment = document.createComment(`with-content`)

  constructor() {
    super(`ref${refchild_counter++}`)
  }

  get isUsed() {
    return this.parentNode != null || this.content_ref.parentNode != null
  }

  IfUsed(fn: (refchild: RefChild) => Renderable<Node>) {
    this.with_content = fn
    this.content_ref = document.createComment(`${this.textContent}-content`)
    return this.content_ref
  }

  override before(...nodes: (Node | string)[]) {
    const ref = this.content_ref
    if (this.with_content != null && ref.parentNode != null) {
      node_append(ref.parentNode, this.with_content(this), ref)
      ref.remove()
      this.with_content = null
    }
    return super.before(...nodes)
  }

  override remove() {
    this.with_content = null
    return super.remove()
  }
}

// Just to avoid Comment allocations
let refchild_counter = 0
let refchildren = new Array<RefChild>(
  32
) /** pre-allocate a size 32, but there is little chance that it will ever reach that size. */
refchildren.length = 0

export type NodeTypeFromCreator<T extends string> =
  // If it is a string of a known HTML element, return it
  T extends keyof HTMLElementTagNameMap
    ? HTMLElementTagNameMap[T]
    : // If it is a string of known SVG element, return it
    T extends keyof SVGElementTagNameMap
    ? SVGElementTagNameMap[T]
    : // Otherwise, it will be a plain HTMLElement
      HTMLElement
export type AttrsFor<T extends string> = T extends keyof ElementMap
  ? ElementMap[T]
  : Attrs<HTMLElement>

/**
 * Create Nodes with a twist.
 *
 * This function is the base of element ; it creates Nodes and glues together
 * Controllers, decorators, classes and style.
 * @category dom, toc
 */
export function e<
  T extends (a: A, refchild: RefChild) => N,
  A extends Attrs<any>,
  N extends Node
>(elt: T, attrs: A, ...children: (A | Renderable<N>)[]): N
export function e<T extends Node>(
  elt: T,
  ...children: (Attrs<T> | Renderable<T>)[]
): T
export function e<T extends string>(
  elt: T,
  ...children: (Renderable<NodeTypeFromCreator<T>> | AttrsFor<T>)[]
): NodeTypeFromCreator<T>
// eslint-disable-next-line @typescript-eslint/ban-types
export function e<N extends Node>(
  elt: string | Node | Function,
  ...children: (Renderable<N> | Attrs<N>)[]
): N {
  let node: N // just to prevent the warnings later

  let is_basic_node = true
  let refchild: RefChild | null = null

  // create a simple DOM node
  if (typeof elt === "string") {
    switch (elt) {
      case "svg":
      case "circle":
      case "clipPath":
      case "defs":
      case "desc":
      case "ellipse":
      case "feBlend":
      case "feColorMatrix":
      case "feComponentTransfer":
      case "feComposite":
      case "feConvolveMatrix":
      case "feDiffuseLighting":
      case "feDisplacementMap":
      case "feDistantLight":
      case "feFlood":
      case "feFuncA":
      case "feFuncB":
      case "feFuncG":
      case "feFuncR":
      case "feGaussianBlur":
      case "feImage":
      case "feMerge":
      case "feMergeNode":
      case "feMorphology":
      case "feOffset":
      case "fePointLight":
      case "feSpecularLighting":
      case "feSpotLight":
      case "feTile":
      case "feTurbulence":
      case "filter":
      case "foreignObject":
      case "g":
      case "image":
      case "line":
      case "linearGradient":
      case "marker":
      case "mask":
      case "metadata":
      case "path":
      case "pattern":
      case "polygon":
      case "polyline":
      case "radialGradient":
      case "rect":
      case "stop":
      case "switch":
      case "symbol":
      case "text":
      case "textPath":
      case "tspan":
      case "use":
      case "view":
        node = document.createElementNS(
          "http://www.w3.org/2000/svg",
          elt
        ) as unknown as N
        break
      default:
        node = document.createElement(elt) as unknown as N
        node[sym_elt_init]?.()
    }
  } else if (typeof elt === "function") {
    // elt is just a creator function
    node =
      elt.length > 1
        ? elt(
            children[0] ?? {},
            (refchild = refchildren[refchild_counter++] ??= new RefChild())
          )
        : elt(children[0] ?? {})

    // if refchild was given but not inserted, set it back to null
    if (refchild != null) {
      if (!refchild.isUsed) {
        refchild_counter--
        refchild = null
      }
    }
    is_basic_node = false
  } else {
    node = elt as N
  }

  for (let i = 0, l = children.length; i < l; i++) {
    node_append(node, children[i], refchild, is_basic_node)
  }

  if (refchild != null) {
    refchild_counter--
    refchild.remove()
  }

  return node
}

/**
 * Creates a document fragment.
 *
 * The JSX namespace points `JSX.Fragment` to this function.
 *
 * > **Note**: Its signature says it expects `Insertable`, but since a document fragment itself never
 * > ends up being added to `Node`, no observable will ever run on it, no life cycle callback will
 * > ever be called on it.
 *
 * ```tsx
 * [[include:../examples/fragment.tsx]]
 * ```
 *
 * @category dom, toc
 */
export const Fragment = document.createDocumentFragment.bind(document)

const $ = Fragment

export namespace e {
  /**
   * Extend the JSX namespace to be able to use .tsx code.
   */
  export namespace JSX {
    /** @internal */
    export type Element = Node

    /** @internal */
    export interface ElementChildrenAttribute {
      $$children: any
    }

    /**
     * The signature function components should conform to.
     * @internal
     */
    export interface ElementClassFn<N extends Node> {
      (attrs: EmptyAttributes<N>, refchild: RefChild): N
    }

    /** @internal */
    export type ElementClass = ElementClassFn<any>

    // This is the line that tells JSX what attributes the basic elements like "div" or "article" have
    export type IntrinsicElements = ElementMap & {
      [name: string]: Attrs<HTMLElement>
    }
  }

  /**
   * An alias to conform to typescript's JSX
   * @internal
   */
  export const createElement = e

  /** @internal */
  export const Fragment: (
    at: EmptyAttributes<DocumentFragment>
  ) => DocumentFragment = $

  export const component = <T extends object, N extends Node>(
    fn: (attrs: T, ch: RefChild) => N
  ): ((a: Attrs<N> & T, ch: RefChild) => N) => fn
}

declare let global: any
if (typeof global !== "undefined" && typeof global.E === "undefined") {
  ;(global as any).E = e
}

if ("undefined" !== typeof window && typeof (window as any).E === "undefined") {
  ;(window as any).E = e
}

declare global {
  const E: typeof e

  namespace E.JSX {
    export type Element = Node
    export type ElementChildrenAttribute = e.JSX.ElementChildrenAttribute
    export type ElementClassFn<N extends Node> = e.JSX.ElementClassFn<N>
    export type ElementClass = e.JSX.ElementClass
    export type IntrinsicElements = e.JSX.IntrinsicElements
  }
}
